<?php
declare(strict_types=1);
require_once __DIR__ . '/../Config/database.php';
require_once __DIR__ . '/../Config/mikrotik.php';
require_once __DIR__ . '/../library/routeros_api.class.php';
ini_set('display_errors','0');header('Content-Type: application/json; charset=utf-8');
function hcd_json(bool $success,string $message='',array $data=[],int $code=200):void{http_response_code($code);echo json_encode(array_merge(['success'=>$success,'message'=>$message],$data),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
function hcd_tables(PDO $pdo):void{$pdo->exec("CREATE TABLE IF NOT EXISTS hotspot_traffic_user_history(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,router_id INT NULL,username VARCHAR(100) NOT NULL,session_id VARCHAR(120) NOT NULL DEFAULT '',recorded_at DATETIME NOT NULL,bytes_in BIGINT UNSIGNED NOT NULL DEFAULT 0,bytes_out BIGINT UNSIGNED NOT NULL DEFAULT 0,upload_bps DECIMAL(20,2) NOT NULL DEFAULT 0,download_bps DECIMAL(20,2) NOT NULL DEFAULT 0,address VARCHAR(64) NOT NULL DEFAULT '',interface_name VARCHAR(150) NOT NULL DEFAULT '',KEY idx_huh_router_user_time(router_id,username,recorded_at),KEY idx_huh_user_session_time(username,session_id,recorded_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");}
function hcd_range(string $r):int{return ['1h'=>1,'6h'=>6,'24h'=>24,'7d'=>168,'30d'=>720][$r]??24;}
function hcd_usage(PDO $pdo,int $routerId,string $user,int $hours):array{$q=$pdo->prepare("SELECT session_id,bytes_in,bytes_out FROM hotspot_traffic_user_history WHERE router_id=? AND username=? AND recorded_at>=DATE_SUB(NOW(),INTERVAL {$hours} HOUR) ORDER BY recorded_at ASC,id ASC");$q->execute([$routerId,$user]);$rows=$q->fetchAll(PDO::FETCH_ASSOC);$down=0;$up=0;$prev=[];foreach($rows as $r){$sid=(string)$r['session_id'];if($sid!==''&&isset($prev[$sid])){$di=(int)$r['bytes_in']-$prev[$sid][0];$do=(int)$r['bytes_out']-$prev[$sid][1];if($di>=0)$up+=$di;if($do>=0)$down+=$do;}$prev[$sid]=[(int)$r['bytes_in'],(int)$r['bytes_out']];}return ['download_bytes'=>(string)$down,'upload_bytes'=>(string)$up,'total_bytes'=>(string)($down+$up),'records'=>count($rows)];}
try{$username=trim((string)($_GET['username']??''));if($username==='')hcd_json(false,'Username Hotspot wajib diisi.',[],400);$range=(string)($_GET['range']??'24h');$hours=hcd_range($range);$config=new MikroTikConfig();$routerId=isset($_GET['router_id'])?(int)$_GET['router_id']:0;$router=$routerId>0?$config->getRouterById($routerId):$config->getRouter();if(!$router)hcd_json(false,'Router tidak ditemukan.',[],404);$routerId=(int)$router['id'];$pdo=(new Database())->connect();hcd_tables($pdo);$api=new RouterosAPI();$api->debug=false;$online=false;$active=null;$secret=null;if($api->connect($router['ip_address'],$router['username'],$router['password'],$router['api_port'])){$raw=(array)$api->comm('/ip/hotspot/active/print');foreach($raw as $row){if(is_array($row)&&strcasecmp(trim((string)($row['user']??'')),$username)===0){$active=$row;break;}}$users=(array)$api->comm('/ip/hotspot/user/print');foreach($users as $row){if(is_array($row)&&strcasecmp(trim((string)($row['name']??'')),$username)===0){$secret=$row;break;}}$online=$active!==null;$api->disconnect();}$st=$pdo->prepare("SELECT * FROM hotspot_traffic_user_history WHERE router_id=? AND username=? AND recorded_at>=DATE_SUB(NOW(),INTERVAL {$hours} HOUR) ORDER BY recorded_at ASC,id ASC");$st->execute([$routerId,$username]);$rows=$st->fetchAll(PDO::FETCH_ASSOC);$labels=[];$download=[];$upload=[];$details=[];$totalDown=0;$totalUp=0;$prev=[];$sumD=0.0;$sumU=0.0;$peakD=0.0;$peakU=0.0;$sessions=[];foreach($rows as $r){$sid=(string)$r['session_id'];$t=strtotime((string)$r['recorded_at']);$d=(float)$r['download_bps'];$u=(float)$r['upload_bps'];$sumD+=$d;$sumU+=$u;$peakD=max($peakD,$d);$peakU=max($peakU,$u);if($sid!==''&&isset($prev[$sid])){$di=(int)$r['bytes_in']-$prev[$sid]['in'];$do=(int)$r['bytes_out']-$prev[$sid]['out'];if($di>=0)$totalUp+=$di;if($do>=0)$totalDown+=$do;}$prev[$sid]=['in'=>(int)$r['bytes_in'],'out'=>(int)$r['bytes_out']];$labels[]=date('H:i:s',$t);$download[]=$d;$upload[]=$u;$details[]=['time'=>(string)$r['recorded_at'],'rx'=>(string)$r['bytes_in'],'tx'=>(string)$r['bytes_out'],'download_bps'=>$d,'upload_bps'=>$u,'address'=>(string)$r['address'],'interface'=>(string)$r['interface_name'],'session_id'=>$sid];if($sid!=='')$sessions[$sid]=true;}$count=count($rows);$latest=$count?$rows[$count-1]:null;$profile=(string)($active['profile']??($secret['profile']??''));$address=(string)($active['address']??($latest['address']??''));$mac=(string)($active['mac-address']??'');$interface=(string)($active['interface']??($latest['interface_name']??''));$uptime=(string)($active['uptime']??'');$loginBy=(string)($active['login-by']??'');$usage7=hcd_usage($pdo,$routerId,$username,168);$usage30=hcd_usage($pdo,$routerId,$username,720);hcd_json(true,'',['router_id'=>$routerId,'router_name'=>(string)$router['name'],'online'=>$online,'user'=>['username'=>$username,'profile'=>$profile,'address'=>$address,'mac_address'=>$mac,'interface'=>$interface,'uptime'=>$uptime,'login_by'=>$loginBy,'comment'=>(string)($secret['comment']??''),'limit_uptime'=>(string)($secret['limit-uptime']??''),'limit_bytes_in'=>(string)($secret['limit-bytes-in']??''),'limit_bytes_out'=>(string)($secret['limit-bytes-out']??'')],'latest_rx'=>(string)($latest['bytes_in']??0),'latest_tx'=>(string)($latest['bytes_out']??0),'average_download_bps'=>$count?$sumD/$count:0,'average_upload_bps'=>$count?$sumU/$count:0,'peak_download_bps'=>$peakD,'peak_upload_bps'=>$peakU,'total_download_bytes'=>(string)$totalDown,'total_upload_bytes'=>(string)$totalUp,'records'=>$count,'sessions'=>count($sessions),'usage_7d'=>$usage7,'usage_30d'=>$usage30,'labels'=>$labels,'download_speed'=>$download,'upload_speed'=>$upload,'details'=>array_reverse(array_slice($details,-150))]);}catch(Throwable $e){hcd_json(false,$e->getMessage(),[],500);}
